"""Check growth protocol arithmetic, independent fixture expectations and rejection gates without Java."""
import argparse
from collections import Counter
from copy import deepcopy
import itertools
import json
from pathlib import Path
import sys

BENCH = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(BENCH))
import analyze_comparison as analysis
import qualify_runtime as qualification
import run_comparison as runner


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', required=True, type=Path)
    args = parser.parse_args()
    need = runner.require
    need(not args.output.exists(), 'Use a fresh static-check receipt')
    for path in BENCH.rglob('*.py'):
        if not any(part.startswith('runtime-') for part in path.relative_to(BENCH).parts):
            compile(path.read_text(), str(path), 'exec')
    expected = runner.read(BENCH / 'fixture-oracles-v1.json')
    for fixture in expected['fixtures']:
        analysis.subset(fixture['expected'], qualification.direct_oracle(fixture['arguments']),
                        'Independent direct-string fixture oracle')
    names = [fixture['id'] for fixture in expected['fixtures']]
    need(tuple(names) == analysis.FIXTURE_IDS and runner.ARMS == analysis.ARMS
         == ('ordinary', 'adaptive', 'fixed'), 'Fixture/arm declaration differs')
    schedule = [(round_index, fixture_position, fixture, arm_position, arm)
                for round_index, order in enumerate(itertools.permutations(runner.ARMS))
                for fixture_position, fixture in enumerate(analysis.fixture_order(names, round_index))
                for arm_position, arm in enumerate(order)]
    need(len(schedule) == 54 and len(set(schedule)) == 54, 'Wrong finite schedule')
    for fixture in names:
        position_counts = Counter(fi for r, fi, name, ai, arm in schedule if name == fixture and ai == 0)
        need(position_counts == {0: 2, 1: 2, 2: 2}, 'Fixture positions are not balanced')
        for arm in runner.ARMS:
            need(Counter(ai for r, fi, name, ai, a in schedule if name == fixture and a == arm)
                 == {0: 2, 1: 2, 2: 2}, 'Arm positions are not balanced')
    rejected = []
    def rejects(label, action):
        try:
            action()
        except ValueError as error:
            rejected.append({'case': label, 'reason': str(error)})
        else:
            raise ValueError('Corruption was accepted: ' + label)
    sample = {key: 10 for key in analysis.METRICS}
    sample.update(phaseCountersValid=True, callerCpuNs=60, callerCpuToPrefixNs=10,
                  callerCpuTailNs=20, callerCpuAfterConsumeNs=30, callerThreadAllocatedBytes=600,
                  callerAllocatedToPrefixBytes=100, callerAllocatedTailBytes=200,
                  callerAllocatedAfterConsumeBytes=300)
    analysis.inspect_phase_metrics(sample, True)
    bad = deepcopy(sample)
    bad['callerCpuTailNs'] += 1
    rejects('caller CPU phase mismatch', lambda: analysis.inspect_phase_metrics(bad, True))
    bad = deepcopy(sample)
    bad['callerAllocatedTailBytes'] += 1
    rejects('caller allocation phase mismatch', lambda: analysis.inspect_phase_metrics(bad, True))
    bad = deepcopy(sample)
    bad['callerCpuToPrefixNs'] = None
    rejects('missing full-consumer prefix counter', lambda: analysis.inspect_phase_metrics(bad, True))
    owner = dict.fromkeys(analysis.OWNER_FIELDS, 0)
    owner.update(ownerOrdinal=1, compileOrdinalAtOpen=1, compileOrdinalAtClose=1,
                 lazyValueCallsAtClose=8192, probes=16384, hits=8192, collisions=3000,
                 resizes=1, peakCapacity=8192, peakArrayBytes=442528, retainedEntriesAtClose=3000,
                 capacityAtClose=8192, weakEntryAllocations=8192, ownerReferenceAllocations=1,
                 peakReservationBytes=1819104, weakRetention=1)
    protocol = {'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                                       'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160}}
    owner_sample = {'counters': {'lazyValueCalls': 8192}, 'ledgerPeakBytes': 1819104}
    analysis.inspect_owner(protocol, owner, owner_sample, 0, 'adaptive')
    rejects('fixed owner grew', lambda: analysis.inspect_owner(protocol, owner, owner_sample, 0, 'fixed'))
    fixed = deepcopy(owner)
    fixed.update(resizes=0, peakCapacity=4096, capacityAtClose=4096, peakArrayBytes=147536,
                 peakReservationBytes=606448)
    analysis.inspect_owner(protocol, fixed, owner_sample, 0, 'fixed')
    bad_owner = deepcopy(fixed)
    bad_owner['lowHitDisable'] = 1
    rejects('always owner reports cutoff', lambda: analysis.inspect_owner(protocol, bad_owner, owner_sample, 0, 'fixed'))
    bad_owner = deepcopy(fixed)
    bad_owner['peakReservationBytes'] += 1
    rejects('fixed reservation charge mismatch', lambda: analysis.inspect_owner(protocol, bad_owner, owner_sample, 0, 'fixed'))
    def metadata(arm):
        properties = {runner.ENABLED: str(arm != 'ordinary').lower(), runner.ADMISSION: 'always',
                      runner.RETENTION: 'weak', runner.GROWTH: 'fixed' if arm == 'fixed' else 'adaptive'}
        return {'arm': arm, 'store': '/synthetic/' + arm, 'admission': 'always',
                'growth': properties[runner.GROWTH], 'systemProperties': properties,
                'jvmArguments': ['-D' + key + '=' + value for key, value in properties.items()]}
    normalized = [analysis.normalized_metadata(metadata(arm)) for arm in runner.ARMS]
    need(normalized[0] == normalized[1] == normalized[2], 'Intentional arm differences did not normalize')
    changed = metadata('fixed')
    changed['admission'] = 'initial'
    need(analysis.normalized_metadata(changed) != normalized[0], 'Admission change was incorrectly normalized away')
    result = {'passed': True, 'javaLaunches': 0, 'syntheticChecksOnly': True, 'scheduleJvms': len(schedule),
              'queries': len(schedule) * 13, 'independentFixtureOracles': len(names),
              'rejectedCorruptions': rejected, 'armNormalization': 'passed',
              'harnessBehaviorNotExecuted': True,
              'sourceHashes': {p.relative_to(BENCH).as_posix(): runner.sha(p) for p in sorted(BENCH.rglob('*'))
                               if p.is_file() and p.suffix in ('.java', '.py', '.md')
                               and not any(part.startswith('runtime-') for part in p.relative_to(BENCH).parts)}}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    runner.write(args.output, result)
    print(json.dumps({key: value for key, value in result.items() if key != 'sourceHashes'}))


if __name__ == '__main__':
    main()
